def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    import heapq

    zcount = len(prices)
    adj = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        adj[u].append((v, cost, zone))
        adj[v].append((u, cost, zone))

    buy = [[] for _ in range(n)]
    seen = [set() for _ in range(n)]
    for stop, z in stations:
        if 0 <= stop < n and 0 <= z < zcount and z not in seen[stop]:
            seen[stop].add(z)
            buy[stop].append(z)

    masks = 1 << zcount
    inf = 10**18
    dist = [[inf] * masks for _ in range(n)]
    dist[0][0] = 0
    pq = [(0, 0, 0)]

    while pq:
        d, u, mask = heapq.heappop(pq)
        if d != dist[u][mask]:
            continue
        if u == n - 1:
            return d
        for z in buy[u]:
            bit = 1 << z
            if mask & bit:
                continue
            nmask = mask | bit
            nd = d + prices[z]
            if nd < dist[u][nmask]:
                dist[u][nmask] = nd
                heapq.heappush(pq, (nd, u, nmask))
        owned = mask
        for v, cost, zone in adj[u]:
            if zone != -1 and (owned & (1 << zone)):
                pay = 0
            else:
                pay = cost
            nd = d + pay
            if nd < dist[v][mask]:
                dist[v][mask] = nd
                heapq.heappush(pq, (nd, v, mask))

    return -1
